export const notazioneLatinaDiesis=["DO","DO#","RE","RE#","MI","FA","FA#","SOL","SOL#","LA","LA#","SI"];export const bemolleToDiesis={REb:"DO#",MIb:"RE#",SOLb:"FA#",LAb:"SOL#",SIb:"LA#"};export const diesisToBemolle={"DO#":"REb","RE#":"MIb","FA#":"SOLb","SOL#":"LAb","LA#":"SIb"};export function containsChord(e){return/^(DO|RE|MI|FA|SOL|LA|SI)([#b]?)(m?|°?|maj7?)(\d*)(\/(DO|RE|MI|FA|SOL|LA|SI)([#b]?)(m?|°?|maj7?)?)?$/.test(e)}export function transposeChord(e,i){let t=e.split("/");return(t=t.map(e=>{let t=e.match(/^([A-Z]+)([#b]?)(m?|°?|maj7?)(\d*)$/);if(!t)return e;let o=t[1].toUpperCase(),n=t[2]||"",s=t[3]||"",a=t[4]||"";"b"===n&&bemolleToDiesis[o+n]&&(o=bemolleToDiesis[o+n],n="");let l=notazioneLatinaDiesis.indexOf(o+n);if(-1!==l){let L=(l+i)%notazioneLatinaDiesis.length;L<0&&(L+=notazioneLatinaDiesis.length);let r=notazioneLatinaDiesis[L];return i<0&&diesisToBemolle[r]&&(r=diesisToBemolle[r]),r+("\xb0"===s?"\xb0":"m"===s?"m":s.includes("maj7")?"maj7":"")+a}return e})).join("/")}